<dialog class="modal" id="address-modal"><div class="modal-head"><h3>افزودن آدرس جدید</h3><button data-close-modal class="icon-button" aria-label="بستن">@include('partials.icon',['name'=>'close'])</button></div><form action="/account/addresses" method="post" data-ajax><div class="form-grid"><label class="field"><span>نام گیرنده</span><input name="name" required maxlength="100" value="{{ auth()->user()?->name }}" autocomplete="name"></label><label class="field"><span>شماره موبایل</span><input name="phone" required inputmode="tel" pattern="09[0-9]{9}" maxlength="11" placeholder="09123456789" value="{{ auth()->user()?->phone }}"></label><label class="field"><span>شهر</span><input name="city" required maxlength="100" autocomplete="address-level2"></label><label class="field"><span>کد پستی ۱۰ رقمی</span><input name="postal_code" required pattern="[0-9]{10}" maxlength="10" inputmode="numeric" autocomplete="postal-code"></label><label class="field full"><span>آدرس کامل</span><textarea name="address" minlength="10" maxlength="1000" required autocomplete="street-address" placeholder="خیابان، کوچه، پلاک، طبقه و واحد"></textarea></label></div><div class="form-errors"></div><button class="btn btn-primary btn-block mt-5">ذخیره آدرس</button></form></dialog>
